def check_dict_case(dictionary):
    if not dictionary:
        return False

    all_lower = all(isinstance(key, str) and key.islower() for key in dictionary.keys())
    all_upper = all(isinstance(key, str) and key.isupper() for key in dictionary.keys())

    return all_lower or all_upper

